{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "In healthy subjects, eravacycline (the query compound) had an absolute oral bioavailability of 28% (range 26–32%) after oral solution doses of 50–300 mg compared with IV, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Omadacycline, a close tetracycline analogue, has an absolute oral bioavailability of 34.5% in humans (300 mg oral vs 100 mg IV), supporting that this structural class can achieve F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Tigecycline, a structurally related glycylcycline, has low oral bioavailability and is IV-only in humans, which would argue against high F if transferred.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct human absolute bioavailability data for eravacycline show 28% (range 26–32%), clearly above the 20% threshold. Supporting data from omadacycline (34.5%) reinforce the class potential, while tigecycline's low oral bioavailability is a less transferable counterexample. Prediction: high.",
  "evidence_gaps": [
    "No material gaps; the highest-transfer record is the same drug (eravacycline) with human absolute bioavailability data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

